style.css:
@-moz-document domain("desmos.com") {
/* Main Background */
    body, .dcg-container {
        background-color: #e0fff7 !important;
    }

    /* Header and Navigation */
    .dcg-header, .dcg-calculator-api-header {
        background-color: #a0f0c0 !important;
        color: #004d40 !important;
    }

    /* Sidebar and Menus */
    .dcg-expressionlist, .dcg-exppanel, .dcg-exppanel-header {
        background-color: #bfffe0 !important;
        color: #004d40 !important;
    }

    /* Graph Paper */
    .dcg-graphpaper {
        background-color: #e0fff7 !important;
    }

    /* Buttons */
    .dcg-btn, .dcg-standard-button {
        background-color: #80e6b0 !important;
        color: #004d40 !important;
        border-color: #66d9a0 !important;
    }

    /* Dropdown Menus */
    .dcg-popover {
        background-color: #a0f0c0 !important;
        color: #004d40 !important;
    }

    /* Hover Effects */
    .dcg-btn:hover, .dcg-standard-button:hover, .dcg-popover:hover {
        background-color: #66d9a0 !important;
    }

    /* Borders */
    .dcg-container, .dcg-exppanel, .dcg-expressionlist, .dcg-popover {
        border-color: #66d9a0 !important;
    }

    /* Text Colors */
    * {
        color: #004d40 !important;
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
